//! Applies in-game addon changes before Fabric opens the profile. Loaded JARs are never changed in game.
use crate::storage::{atomic, read_json, Context, Result};
use serde::Deserialize;
use serde_json::{json, Value};
use sha2::{Digest, Sha512};
use std::{collections::{BTreeMap, BTreeSet}, fs, io::{Read, Write}, path::{Component, Path, PathBuf}};
const MAX_FILE:u64=128*1024*1024;
#[derive(Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
struct Queue { schema_version:u32, actions:Vec<Action> }
#[derive(Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
struct Action { kind:String, folder:String, filename:String, #[serde(default)] staged:Option<String>, #[serde(default)] sha512:Option<String>, #[serde(default)] source_sha512:Option<String>, #[serde(default)] replaces:Vec<String>, #[serde(default)] replace_hashes:BTreeMap<String,String>, #[serde(default)] metadata:Option<Value> }
fn filename(value:&str)->Result<()> {
 if value.is_empty()||value.chars().count()>180||value=="."||value==".."||value.ends_with('.')||value.ends_with(' ')||value.chars().any(|c|c<' '||"<>:\"/\\|?*".contains(c)) {return Err("Unsicherer Dateiname in der Ingame-Änderungsliste".into());}
 let stem=value.split('.').next().unwrap_or("").to_ascii_uppercase();
 if ["CON","PRN","AUX","NUL"].contains(&stem.as_str()) || (stem.len()==4&&(stem.starts_with("COM")||stem.starts_with("LPT"))&&stem.as_bytes()[3]>=b'1'&&stem.as_bytes()[3]<=b'9'){return Err("Reservierter Dateiname in der Änderungsliste".into());}
 Ok(())
}
fn ensure_dir(root:&Path,relative:&Path)->Result<PathBuf>{let mut current=root.to_path_buf();for c in relative.components(){let Component::Normal(part)=c else{return Err("Unsicherer Erweiterungspfad".into())};current.push(part);if current.exists(){if !fs::canonicalize(&current).context("Erweiterungsordner prüfen")?.starts_with(root)||!current.is_dir(){return Err("Erweiterungsordner verlässt das Profil".into());}}else{fs::create_dir(&current).context("Erweiterungsordner anlegen")?;}}Ok(current)}
fn inside(root:&Path,relative:&Path)->Result<PathBuf>{let parent=relative.parent().ok_or("Datei ohne Elternordner")?;let dir=ensure_dir(root,parent)?;let file=relative.file_name().ok_or("Ungültiger Dateipfad")?;let path=dir.join(file);if path.exists()&&(!path.is_file()||!fs::canonicalize(&path).context("Erweiterungsdatei prüfen")?.starts_with(root)){return Err("Erweiterungsdatei verlässt das Profil".into());}Ok(path)}
fn digest(path:&Path)->Result<String>{if fs::metadata(path).context("Erweiterung prüfen")?.len()>MAX_FILE{return Err("Erweiterung überschreitet 128 MiB".into());}let mut file=fs::File::open(path).context("Erweiterung öffnen")?;let mut sum=Sha512::new();let mut bytes=[0u8;65536];let mut total=0u64;loop{let n=file.read(&mut bytes).context("Erweiterung lesen")?;if n==0{break;}total+=n as u64;if total>MAX_FILE{return Err("Erweiterung überschreitet 128 MiB".into());}sum.update(&bytes[..n]);}Ok(hex::encode(sum.finalize()))}
fn hash(value:&str)->Result<()>{if value.len()!=128||!value.bytes().all(|c|c.is_ascii_hexdigit()){return Err("Ungültige SHA-512-Prüfsumme".into());}Ok(())}
fn copy_atomic(source:&Path,target:&Path)->Result<()>{copy_atomic_checked(source,target,None)}
fn copy_atomic_checked(source:&Path,target:&Path,expected:Option<&str>)->Result<()>{let temporary=target.with_file_name(format!(".votex-stage-{}",uuid::Uuid::new_v4()));let result=(||{let from=fs::File::open(source).context("Geprüfte Erweiterung lesen")?;let mut to=fs::OpenOptions::new().write(true).create_new(true).open(&temporary).context("Erweiterung vorbereiten")?;let copied=std::io::copy(&mut from.take(MAX_FILE+1),&mut to).context("Erweiterung kopieren")?;if copied>MAX_FILE{return Err("Erweiterung überschreitet 128 MiB".into());}to.flush().context("Erweiterung schreiben")?;to.sync_all().context("Erweiterung sichern")?;drop(to);if let Some(hash)=expected{if digest(&temporary)?!=hash.to_ascii_lowercase(){return Err("Datei wurde während der Installation geändert".into());}}if target.exists(){fs::remove_file(target).context("Gesicherte alte Erweiterung ersetzen")?;}fs::rename(&temporary,target).context("Erweiterung aktivieren")})();if temporary.exists(){let _=fs::remove_file(&temporary);}result}
fn source(action:&Action)->PathBuf{Path::new(&action.folder).join(&action.filename)}
fn target(action:&Action)->PathBuf{let name=match action.kind.as_str(){"disable"=>format!("{}.disabled",action.filename),"enable"=>action.filename.trim_end_matches(".disabled").to_string(),_=>action.filename.clone()};Path::new(&action.folder).join(name)}
// A durable pre-mutation journal lets a launch interrupted by a crash restore its exact originals.
fn recover(root:&Path)->Result<()> {
 let journal=inside(root,Path::new("config/votex/addon-transaction.json"))?;if !journal.exists(){return Ok(());}if fs::metadata(&journal).context("Transaktion prüfen")?.len()>512*1024{return Err("Erweiterungstransaktion überschreitet das Limit".into());}let data=read_json(&journal)?;if data["schemaVersion"]!=1{return Err("Unbekannte Erweiterungstransaktion".into());}let batch=data["batch"].as_str().ok_or("Sicherungskennung fehlt")?;uuid::Uuid::parse_str(batch).map_err(|_|"Ungültige Sicherungskennung")?;let files=data["files"].as_array().ok_or("Transaktionsdateien fehlen")?;if files.len()>401{return Err("Zu viele Transaktionsdateien".into());}let backup_relative=Path::new("config/votex/addon-backups").join(batch);let mut checked=vec![];let mut recovery_keys=BTreeSet::new();let mut recovery_bytes=0u64;
 for file in files{let relative=PathBuf::from(file["path"].as_str().ok_or("Transaktionspfad fehlt")?);let parts:Vec<_>=relative.components().collect();if parts.len()!=2||!matches!(parts[0],Component::Normal(_))||!matches!(parts[1],Component::Normal(_)){return Err("Unsicherer Transaktionspfad".into());}let folder=parts[0].as_os_str().to_str().ok_or("Ungültiger Ordner")?;let name=parts[1].as_os_str().to_str().ok_or("Ungültiger Dateiname")?;if !["mods","resourcepacks","shaderpacks"].contains(&folder){return Err("Unsicherer Transaktionsordner".into());}filename(name)?;if !recovery_keys.insert(relative.to_string_lossy().to_uppercase()){return Err("Doppelter Transaktionspfad".into());}let existed=file["existed"].as_bool().ok_or("Transaktionszustand fehlt")?;let target=inside(root,&relative)?;let original=inside(root,&backup_relative.join(&relative))?;let expected=if existed{if !original.exists(){return Err("Eine Originalsicherung der Erweiterungen fehlt".into());}let expected=file["sha512"].as_str().ok_or("Prüfsumme der Originalsicherung fehlt")?;hash(expected)?;let size=fs::metadata(&original).context("Originalsicherung prüfen")?.len();recovery_bytes+=size;if recovery_bytes>1024*1024*1024{return Err("Originalsicherungen überschreiten 1 GiB".into());}if digest(&original)?!=expected.to_ascii_lowercase(){return Err("Eine Originalsicherung wurde nachträglich verändert".into());}Some(expected.to_ascii_lowercase())}else{None};checked.push((target,original,existed,expected));}
 for(target,original,existed,expected)in checked{if existed{copy_atomic_checked(&original,&target,expected.as_deref())?;}else if target.exists(){fs::remove_file(&target).context("Unterbrochene neue Erweiterung zurücknehmen")?;}}
 let archived=inside(root,&backup_relative.join("applied-queue.json"))?;let queue=inside(root,Path::new("config/votex/addon-queue.json"))?;if archived.exists()&&!queue.exists(){copy_atomic(&archived,&queue)?;}fs::remove_file(journal).context("Wiederhergestellte Transaktion abschließen")?;Ok(())
}
/// Call before `prepare::profile`/Minecraft spawn, after the previous game process has exited.
/// A preflight validates every staged file; originals are backed up before any profile mutation.
pub fn apply(instance:&Path)->Result<()> {
 if !instance.exists(){return Ok(());}
 let root=fs::canonicalize(instance).context("Profil für Ingame-Änderungen öffnen")?;
 recover(&root)?;
 let queue_path=inside(&root,Path::new("config/votex/addon-queue.json"))?;if !queue_path.exists(){return Ok(());}if fs::metadata(&queue_path).context("Änderungsliste prüfen")?.len()>512*1024{return Err("Ingame-Änderungsliste überschreitet das Limit".into());}
 let queue:Queue=serde_json::from_slice(&fs::read(&queue_path).context("Ingame-Änderungen lesen")?).context("Ungültige Ingame-Änderungsliste")?;if queue.schema_version!=1||queue.actions.len()>100{return Err("Nicht unterstützte Ingame-Änderungsliste".into());}if queue.actions.is_empty(){return Ok(());}
 let mut all_paths=BTreeMap::<String,PathBuf>::new();let mut affected_keys=BTreeSet::new();let mut staged=BTreeMap::new();let mut total=0u64;
 for (index,action) in queue.actions.iter().enumerate(){filename(&action.filename)?;if !["mods","shaderpacks","resourcepacks"].contains(&action.folder.as_str())||!["install","disable","enable","remove"].contains(&action.kind.as_str()){return Err("Unbekannte Ingame-Erweiterungsaktion".into());}if action.filename.to_ascii_lowercase().starts_with("votex-client-core-"){return Err("Votex Core wird vom Launcher verwaltet".into());}
  let valid_source=if action.folder=="mods"{action.filename.ends_with(".jar")||action.filename.ends_with(".jar.disabled")}else{action.filename.ends_with(".zip")};if !valid_source{return Err("Falsches Erweiterungsformat in der Änderungsliste".into());}let mut paths=BTreeSet::new();paths.insert(source(action));if action.kind=="install" {let extension=if action.folder=="mods"{".jar"}else{".zip"};if !action.filename.ends_with(extension){return Err("Falsches Erweiterungsformat".into());}let sum=action.sha512.as_deref().ok_or("Prüfsumme fehlt")?;hash(sum)?;let expected=format!("{}.bin",sum.to_ascii_lowercase());if action.staged.as_deref()!=Some(expected.as_str()){return Err("Unsicherer Staging-Dateiname".into());}let file=inside(&root,&Path::new("config/votex/addon-staging").join(&expected))?;if !file.exists()||digest(&file)?!=sum.to_ascii_lowercase(){return Err("Die vorgemerkte Erweiterung ist unvollständig oder ihre Prüfsumme stimmt nicht".into());}total+=fs::metadata(&file).context("Staging-Datei prüfen")?.len();if total>512*1024*1024{return Err("Erweiterungsplan überschreitet 512 MiB".into());}staged.insert(index,file);if action.replaces.len()>30{return Err("Zu viele ersetzte Dateien".into());}for old in &action.replaces{filename(old)?;if !(if action.folder=="mods"{old.ends_with(".jar")||old.ends_with(".jar.disabled")}else{old.ends_with(".zip")}){return Err("Falsches Format einer ersetzten Erweiterung".into());}if old.to_ascii_lowercase().starts_with("votex-client-core-"){return Err("Votex Core darf nicht ersetzt werden".into());}let relative=Path::new(&action.folder).join(old);let existing=inside(&root,&relative)?;if existing.exists(){let expected=action.replace_hashes.get(old).ok_or("Prüfsumme der ersetzten Datei fehlt")?;hash(expected)?;if digest(&existing)?!=expected.to_ascii_lowercase(){return Err(format!("Die bisherige Datei {old} wurde seit der Vormerkung geändert"));}}paths.insert(relative);}let existing=inside(&root,&source(action))?;if existing.exists()&&!action.replaces.iter().any(|name|name.to_uppercase()==action.filename.to_uppercase()){return Err("Ein neues Installationsziel ist inzwischen bereits vorhanden".into());}}
  else{let file=inside(&root,&source(action))?;let expected=action.source_sha512.as_deref().ok_or("Prüfsumme der bisherigen Datei fehlt")?;hash(expected)?;if !file.exists()||digest(&file)?!=expected.to_ascii_lowercase(){return Err(format!("{} wurde seit der Vormerkung geändert. Bitte die Änderung im Spiel neu anlegen.",action.filename));}if action.kind=="disable"&&(!action.filename.ends_with(".jar")||action.folder!="mods"){return Err("Nur JAR-Mods können deaktiviert werden".into());}if action.kind=="enable"&&(!action.filename.ends_with(".jar.disabled")||action.folder!="mods"){return Err("Nur deaktivierte JAR-Mods können aktiviert werden".into());}if matches!(action.kind.as_str(),"disable"|"enable"){let destination=target(action);if inside(&root,&destination)?.exists(){return Err("Der Zielname der umgeschalteten Mod existiert bereits".into());}paths.insert(destination);}}
  let keys:BTreeSet<String>=paths.iter().map(|p|p.to_string_lossy().to_uppercase()).collect();for key in keys{if !affected_keys.insert(key){return Err("Zwei vorgemerkte Änderungen betreffen dieselbe Datei (Groß-/Kleinschreibung zählt nicht). Bitte die Vormerkung korrigieren.".into());}}for path in paths{inside(&root,&path)?;all_paths.entry(path.to_string_lossy().to_uppercase()).or_insert(path);}if all_paths.len()>400{return Err("Erweiterungsplan betrifft mehr als 400 Dateien".into());}
 }
 let metadata_relative=PathBuf::from("mods/installed.json");let metadata_path=inside(&root,&metadata_relative)?;let mut metadata=if metadata_path.exists(){if fs::metadata(&metadata_path).context("Mod-Metadaten prüfen")?.len()>4*1024*1024{return Err("Mod-Metadaten überschreiten das Limit".into());}read_json(&metadata_path)?}else{json!([])};let records=metadata.as_array_mut().ok_or("Ungültige installierte Mod-Metadaten")?;
 for action in &queue.actions {if action.folder!="mods"{continue;}if action.kind=="remove"{records.retain(|record|record["filename"].as_str().map(|name|name.to_uppercase()!=action.filename.trim_end_matches(".disabled").to_uppercase()).unwrap_or(true));}else if action.kind=="install"{let mut record=action.metadata.clone().ok_or("Installations-Metadaten fehlen")?;if !record.is_object(){return Err("Ungültige Installations-Metadaten".into());}let pid=record["project_id"].as_str().ok_or("Projektkennung fehlt")?.to_string();record["filename"]=json!(action.filename);records.retain(|old|old["project_id"].as_str()!=Some(pid.as_str())&&old["filename"].as_str().map(|name|name.to_uppercase()!=action.filename.to_uppercase()&&!action.replaces.iter().any(|replaced|name.to_uppercase()==replaced.trim_end_matches(".disabled").to_uppercase())).unwrap_or(true));records.push(record);}}
 let metadata_bytes=serde_json::to_vec_pretty(&metadata).context("Mod-Metadaten vorbereiten")?;if metadata_bytes.len()>4*1024*1024{return Err("Neue Mod-Metadaten überschreiten das Limit".into());}
 all_paths.insert(metadata_relative.to_string_lossy().to_uppercase(),metadata_relative.clone());let batch=uuid::Uuid::new_v4().to_string();let backup=ensure_dir(&root,&Path::new("config/votex/addon-backups").join(&batch))?;let mut snapshots=BTreeMap::new();let mut backup_bytes=0;
 for relative in all_paths.values(){let path=inside(&root,relative)?;let exists=path.exists();if exists{backup_bytes+=fs::metadata(&path).context("Original prüfen")?.len();if backup_bytes>1024*1024*1024{return Err("Sicherung der Erweiterungen überschreitet 1 GiB".into());}let expected=digest(&path)?;let copy=backup.join(relative);fs::create_dir_all(copy.parent().unwrap()).context("Sicherung anlegen")?;copy_atomic_checked(&path,&copy,Some(&expected))?;snapshots.insert(relative.clone(),Some(expected));}else{snapshots.insert(relative.clone(),None);}}
 let journal_path=inside(&root,Path::new("config/votex/addon-transaction.json"))?;let files:Vec<Value>=snapshots.iter().map(|(path,hash)|json!({"path":path.to_string_lossy().replace('\\',"/"),"existed":hash.is_some(),"sha512":hash})).collect();atomic(&journal_path,&serde_json::to_vec(&json!({"schemaVersion":1,"batch":batch,"files":files})).context("Transaktion vorbereiten")?)?;
 let result=(||->Result<()>{for (index,action) in queue.actions.iter().enumerate(){let path=inside(&root,&source(action))?;match action.kind.as_str(){"install"=>{for old in &action.replaces{let previous=inside(&root,&Path::new(&action.folder).join(old))?;if previous.exists(){fs::remove_file(previous).context("Gesicherte Mod-Version ersetzen")?;}}copy_atomic_checked(staged.get(&index).unwrap(),&path,action.sha512.as_deref())?;},"remove"=>{if path.exists(){fs::remove_file(path).context("Gesicherte Erweiterung entfernen")?;}},"disable"|"enable"=>{copy_atomic(&backup.join(source(action)),&inside(&root,&target(action))?)?;fs::remove_file(path).context("Bisherige Mod-Variante ersetzen")?;},_=>unreachable!()}}atomic(&metadata_path,&metadata_bytes)?;fs::rename(&queue_path,backup.join("applied-queue.json")).context("Angewendete Änderungsliste archivieren")?;Ok(())})();
 if let Err(error)=result{let recovery=recover(&root);return Err(format!("Ingame-Erweiterungsänderung fehlgeschlagen; Sicherung: {}. {error}; {}",backup.display(),match recovery{Ok(())=>"bisheriger Zustand wiederhergestellt".to_string(),Err(problem)=>format!("Wiederherstellung prüfen: {problem}")}));}
 fs::remove_file(journal_path).context("Abgeschlossene Erweiterungstransaktion sichern")?;
 Ok(())
}
#[cfg(test)]
mod tests {
 use super::*;
 #[test]
 #[ignore="requires an explicitly selected retained isolated mixed Java staging fixture"]
 fn applies_native_java_mixed_staging_fixture() {
  let fixture = PathBuf::from(std::env::var("VOTEX_ADDON_NATIVE_FIXTURE").expect("VOTEX_ADDON_NATIVE_FIXTURE missing"));
  assert_eq!(fixture.file_name().and_then(|name| name.to_str()), Some("clientGameTest"));
  assert!(matches!(fixture.parent().and_then(Path::file_name).and_then(|name| name.to_str()), Some("full-regression-run-04" | "full-regression-run-07")), "Refusing an unrecognized native evidence directory");
  let queue_path = fixture.join("config/votex/addon-queue.json");
  let original_bytes = fs::read(&queue_path).unwrap();
  let original: Queue = serde_json::from_slice(&original_bytes).unwrap();
  assert_eq!(original.actions.len(), 2);
  let (_temp, root) = setup();
  fs::write(root.join("config/votex/addon-queue.json"), &original_bytes).unwrap();
  let expected = [("mods", "votex-native-library-fixture.jar"), ("shaderpacks", "votex-feedback-fixture.zip")];
  for (action, (folder, name)) in original.actions.iter().zip(expected) {
   assert_eq!(action.kind, "install");
   assert_eq!(action.folder, folder);
   assert_eq!(action.filename, name);
   let checksum = action.sha512.as_ref().unwrap();
   hash(checksum).unwrap();
   let staged = action.staged.as_ref().unwrap();
   assert_eq!(staged, &format!("{checksum}.bin"));
   let source = fixture.join("config/votex/addon-staging").join(staged);
   assert!(!fs::symlink_metadata(&source).unwrap().file_type().is_symlink());
   assert_eq!(digest(&source).unwrap(), checksum.to_ascii_lowercase());
   fs::copy(source, root.join("config/votex/addon-staging").join(staged)).unwrap();
  }
  apply(&root).unwrap();
  for action in &original.actions {
   let expected_hash = action.sha512.as_ref().unwrap().to_ascii_lowercase();
   assert_eq!(digest(&root.join(&action.folder).join(&action.filename)).unwrap(), expected_hash);
   assert_eq!(digest(&fixture.join("config/votex/addon-staging").join(action.staged.as_ref().unwrap())).unwrap(), expected_hash);
  }
  assert_eq!(fs::read(queue_path).unwrap(), original_bytes, "Native evidence must remain unchanged");
  assert!(!root.join("config/votex/addon-queue.json").exists());
  assert!(!root.join("config/votex/addon-transaction.json").exists());
  let backups: Vec<_> = fs::read_dir(root.join("config/votex/addon-backups")).unwrap().map(|entry| entry.unwrap().path()).collect();
  assert_eq!(backups.len(), 1);
  assert_eq!(fs::read(backups[0].join("applied-queue.json")).unwrap(), original_bytes);
  let metadata = read_json(&root.join("mods/installed.json")).unwrap();
  let entries = metadata.as_array().unwrap();
  assert_eq!(entries.len(), 1, "Shader must not be registered as a mod");
  assert_eq!(entries[0]["filename"], expected[0].1);
  assert_eq!(entries[0]["project_id"], "local-votex_native_library_fixture");
 }
 fn setup()->(tempfile::TempDir,PathBuf){let temp=tempfile::tempdir().unwrap();let instance=temp.path().join("instance");fs::create_dir_all(instance.join("config/votex/addon-staging")).unwrap();fs::create_dir_all(instance.join("mods")).unwrap();(temp,instance)}
 fn write_queue(root:&Path,actions:Value){atomic(&root.join("config/votex/addon-queue.json"),&serde_json::to_vec(&json!({"schemaVersion":1,"actions":actions})).unwrap()).unwrap();}
 #[test]fn corrupt_recovery_backup_is_rejected_before_any_mutation(){let(_temp,root)=setup();let batch=uuid::Uuid::new_v4().to_string();let backup=root.join("config/votex/addon-backups").join(&batch);fs::create_dir_all(backup.join("mods")).unwrap();fs::write(backup.join("mods/old.jar"),b"tampered").unwrap();fs::write(root.join("mods/new.jar"),b"current new file").unwrap();atomic(&root.join("config/votex/addon-transaction.json"),&serde_json::to_vec(&json!({"schemaVersion":1,"batch":batch,"files":[{"path":"mods/new.jar","existed":false},{"path":"mods/old.jar","existed":true,"sha512":hex::encode(Sha512::digest(b"original"))}]})).unwrap()).unwrap();let physical=fs::canonicalize(&root).unwrap();assert!(recover(&physical).unwrap_err().contains("nachträglich"));assert_eq!(fs::read(root.join("mods/new.jar")).unwrap(),b"current new file");assert!(root.join("config/votex/addon-transaction.json").exists());}
 #[test]fn oversized_recovery_backup_is_rejected_without_copy(){let(_temp,root)=setup();let batch=uuid::Uuid::new_v4().to_string();let backup=root.join("config/votex/addon-backups").join(&batch);fs::create_dir_all(backup.join("mods")).unwrap();let oversized=fs::File::create(backup.join("mods/old.jar")).unwrap();oversized.set_len(MAX_FILE+1).unwrap();atomic(&root.join("config/votex/addon-transaction.json"),&serde_json::to_vec(&json!({"schemaVersion":1,"batch":batch,"files":[{"path":"mods/old.jar","existed":true,"sha512":"a".repeat(128)}]})).unwrap()).unwrap();let physical=fs::canonicalize(&root).unwrap();assert!(recover(&physical).unwrap_err().contains("128 MiB"));assert!(!root.join("mods/old.jar").exists());}
 #[test]fn duplicate_case_recovery_paths_are_rejected_without_mutation(){let(_temp,root)=setup();fs::write(root.join("mods/keep.jar"),b"keep").unwrap();let batch=uuid::Uuid::new_v4().to_string();atomic(&root.join("config/votex/addon-transaction.json"),&serde_json::to_vec(&json!({"schemaVersion":1,"batch":batch,"files":[{"path":"mods/keep.jar","existed":false},{"path":"mods/KEEP.jar","existed":false}]})).unwrap()).unwrap();let physical=fs::canonicalize(&root).unwrap();assert!(recover(&physical).unwrap_err().contains("Doppelter"));assert_eq!(fs::read(root.join("mods/keep.jar")).unwrap(),b"keep");}
 #[test]fn replacement_with_different_case_keeps_one_recoverable_original(){let(_temp,root)=setup();fs::write(root.join("mods/Foo.jar"),b"old").unwrap();let sum=hex::encode(Sha512::digest(b"new"));fs::write(root.join(format!("config/votex/addon-staging/{sum}.bin")),b"new").unwrap();write_queue(&root,json!([{"kind":"install","folder":"mods","filename":"Foo.jar","staged":format!("{sum}.bin"),"sha512":sum,"replaces":["foo.jar"],"replaceHashes":{"foo.jar":hex::encode(Sha512::digest(b"old"))},"metadata":{"project_id":"new","id":"v"}}]));apply(&root).unwrap();let backup=fs::read_dir(root.join("config/votex/addon-backups")).unwrap().next().unwrap().unwrap().path();assert_eq!(fs::read(backup.join("mods/Foo.jar")).unwrap(),b"old");assert_eq!(fs::read(root.join("mods/Foo.jar")).unwrap(),b"new");}
 #[test]#[ignore="requires the isolated native Java staging fixture from the consolidated game run"]fn applies_native_java_staging_fixture(){let fixture=PathBuf::from(std::env::var("VOTEX_ADDON_NATIVE_FIXTURE").expect("VOTEX_ADDON_NATIVE_FIXTURE missing"));assert!(fixture.to_string_lossy().to_ascii_lowercase().contains("clientgametest"),"Refusing non-isolated fixture");let(_temp,root)=setup();let queue=fixture.join("config/votex/addon-queue.json");fs::copy(&queue,root.join("config/votex/addon-queue.json")).unwrap();let original:Queue=serde_json::from_slice(&fs::read(queue).unwrap()).unwrap();assert_eq!(original.actions.len(),1,"Native test leaves one synthetic import staged");let action=&original.actions[0];assert_eq!(action.filename,"votex-native-library-fixture.jar");let staged=action.staged.as_ref().unwrap();fs::copy(fixture.join("config/votex/addon-staging").join(staged),root.join("config/votex/addon-staging").join(staged)).unwrap();apply(&root).unwrap();assert_eq!(digest(&root.join("mods").join(&action.filename)).unwrap(),action.sha512.as_ref().unwrap().to_ascii_lowercase());assert!(!root.join("config/votex/addon-queue.json").exists());assert_eq!(read_json(&root.join("mods/installed.json")).unwrap()[0]["filename"],action.filename);}

 #[test]fn validates_windows_paths_and_hashes(){for value in ["../evil.jar","x:y.jar","CON.jar","x.jar ","a/b.jar"]{assert!(filename(value).is_err());}assert!(filename("Sodium-26.2.jar").is_ok());assert!(hash(&"a".repeat(128)).is_ok());assert!(hash("wrong").is_err());}
 #[test]fn applies_install_and_retains_old_file_in_backup(){let(_temp,root)=setup();let old=root.join("mods/old.jar");fs::write(&old,b"old").unwrap();let bytes=b"verified bytes";let sum=hex::encode(Sha512::digest(bytes));fs::write(root.join(format!("config/votex/addon-staging/{sum}.bin")),bytes).unwrap();write_queue(&root,json!([{"kind":"install","folder":"mods","filename":"new.jar","staged":format!("{sum}.bin"),"sha512":sum,"replaces":["old.jar"],"replaceHashes":{"old.jar":hex::encode(Sha512::digest(b"old"))},"metadata":{"project_id":"abc","id":"version"}}]));apply(&root).unwrap();assert!(!old.exists());assert_eq!(fs::read(root.join("mods/new.jar")).unwrap(),bytes);assert!(!root.join("config/votex/addon-queue.json").exists());let backups=fs::read_dir(root.join("config/votex/addon-backups")).unwrap().next().unwrap().unwrap().path();assert_eq!(fs::read(backups.join("mods/old.jar")).unwrap(),b"old");assert_eq!(read_json(&root.join("mods/installed.json")).unwrap()[0]["filename"],"new.jar");}
 #[test]fn corrupt_download_does_not_change_original(){let(_temp,root)=setup();fs::write(root.join("mods/old.jar"),b"old").unwrap();let sum="a".repeat(128);fs::write(root.join(format!("config/votex/addon-staging/{sum}.bin")),b"wrong").unwrap();write_queue(&root,json!([{"kind":"install","folder":"mods","filename":"new.jar","staged":format!("{sum}.bin"),"sha512":sum,"replaces":["old.jar"],"metadata":{"project_id":"abc"}}]));assert!(apply(&root).is_err());assert_eq!(fs::read(root.join("mods/old.jar")).unwrap(),b"old");assert!(!root.join("mods/new.jar").exists());}
 #[test]fn crash_journal_restores_original_and_archived_queue(){let(_temp,root)=setup();let batch=uuid::Uuid::new_v4().to_string();let backup=root.join("config/votex/addon-backups").join(&batch);fs::create_dir_all(backup.join("mods")).unwrap();fs::write(backup.join("mods/old.jar"),b"original").unwrap();fs::write(root.join("mods/old.jar"),b"partial update").unwrap();fs::write(root.join("mods/new.jar"),b"partial new file").unwrap();fs::write(backup.join("applied-queue.json"),b"{\"schemaVersion\":1,\"actions\":[]}").unwrap();atomic(&root.join("config/votex/addon-transaction.json"),&serde_json::to_vec(&json!({"schemaVersion":1,"batch":batch,"files":[{"path":"mods/old.jar","existed":true,"sha512":hex::encode(Sha512::digest(b"original"))},{"path":"mods/new.jar","existed":false}]})).unwrap()).unwrap();let physical=fs::canonicalize(&root).unwrap();recover(&physical).unwrap();assert_eq!(fs::read(root.join("mods/old.jar")).unwrap(),b"original");assert!(!root.join("mods/new.jar").exists());assert!(root.join("config/votex/addon-queue.json").exists());assert!(!root.join("config/votex/addon-transaction.json").exists());}
 #[test]fn replacement_changed_after_queue_is_rejected_without_mutation(){let(_temp,root)=setup();fs::write(root.join("mods/old.jar"),b"modified").unwrap();let sum=hex::encode(Sha512::digest(b"new"));fs::write(root.join(format!("config/votex/addon-staging/{sum}.bin")),b"new").unwrap();write_queue(&root,json!([{"kind":"install","folder":"mods","filename":"new.jar","staged":format!("{sum}.bin"),"sha512":sum,"replaces":["old.jar"],"replaceHashes":{"old.jar":hex::encode(Sha512::digest(b"original"))},"metadata":{"project_id":"abc","id":"x"}}]));assert!(apply(&root).is_err());assert_eq!(fs::read(root.join("mods/old.jar")).unwrap(),b"modified");assert!(!root.join("mods/new.jar").exists());}
 #[test]fn case_variants_cannot_target_the_same_file_twice(){let(_temp,root)=setup();let sum=hex::encode(Sha512::digest(b"mod"));fs::write(root.join(format!("config/votex/addon-staging/{sum}.bin")),b"mod").unwrap();write_queue(&root,json!([{"kind":"install","folder":"mods","filename":"Foo.jar","staged":format!("{sum}.bin"),"sha512":sum,"metadata":{"project_id":"abc","id":"x"}},{"kind":"install","folder":"mods","filename":"foo.jar","staged":format!("{sum}.bin"),"sha512":sum,"metadata":{"project_id":"def","id":"y"}}]));assert!(apply(&root).unwrap_err().contains("Groß-/Kleinschreibung"));assert!(!root.join("mods/foo.jar").exists());}
 #[test]fn rejects_folder_symlinks_outside_profile(){let(_temp,root)=setup();let outside=tempfile::tempdir().unwrap();fs::remove_dir(root.join("mods")).unwrap();#[cfg(windows)]{let result=std::process::Command::new("cmd").args(["/C","mklink","/J"]).arg(root.join("mods")).arg(outside.path()).output().unwrap();assert!(result.status.success(),"junction fixture could not be created: {}",String::from_utf8_lossy(&result.stderr));}#[cfg(unix)]std::os::unix::fs::symlink(outside.path(),root.join("mods")).unwrap();let sum=hex::encode(Sha512::digest(b"mod"));fs::write(root.join(format!("config/votex/addon-staging/{sum}.bin")),b"mod").unwrap();write_queue(&root,json!([{"kind":"install","folder":"mods","filename":"escape.jar","staged":format!("{sum}.bin"),"sha512":sum,"metadata":{"project_id":"abc","id":"x"}}]));assert!(apply(&root).is_err());assert!(!outside.path().join("escape.jar").exists());}
 #[test]fn toggles_only_at_restart_and_rejects_changed_original(){let(_temp,root)=setup();let path=root.join("mods/test.jar");fs::write(&path,b"mod").unwrap();let sum=digest(&path).unwrap();write_queue(&root,json!([{"kind":"disable","folder":"mods","filename":"test.jar","sourceSha512":sum}]));assert!(path.exists());apply(&root).unwrap();assert!(!path.exists());assert_eq!(fs::read(root.join("mods/test.jar.disabled")).unwrap(),b"mod");write_queue(&root,json!([{"kind":"enable","folder":"mods","filename":"test.jar.disabled","sourceSha512":"a".repeat(128)}]));assert!(apply(&root).is_err());assert!(!path.exists());}
}
